blocks.loader:
if (load_addr >= 'h33000 && load_addr < 'h34000) begin
    if (load_addr[0]) begin
        mcu_rom_odd[load_addr[11:1]]<=load_data[7:0];
        mcu_rom_even[load_addr[11:1]+11'd1]<=load_data[15:8];
    end else begin
        mcu_rom_even[load_addr[11:1]]<=load_data[7:0];
        mcu_rom_odd[load_addr[11:1]]<=load_data[15:8];
    end
end

blocks.program_q_declaration:
logic [7:0] sting_mcu_even_q=0, sting_mcu_odd_q=0;
logic sting_mcu_program_odd_q=0;
wire [7:0] sting_mcu_program_q=sting_mcu_program_odd_q ? sting_mcu_odd_q : sting_mcu_even_q;

blocks.debug_function:
function automatic [7:0] mcu_debug_byte(input [11:0] addr);
    mcu_debug_byte=addr[0] ? mcu_rom_odd[addr[11:1]] : mcu_rom_even[addr[11:1]];
endfunction
